#!/usr/bin/env python3
"""Write site/factory/dinis-cruz/account-f/data-status.json from the live API index and each source's health.json (in a News__Data checkout).
Run from the News__Data repo root, then copy the output into the home repo. One row per dataset: source, last refresh, items held, freshness, owner, what blocks it."""
import json, re, datetime, sys, urllib.request
now = datetime.datetime.now(datetime.timezone.utc)
ix = json.load(urllib.request.urlopen('https://data.promptugal.news/api/v1/index.json', timeout=30))
def hrs(c):
    c = (c or '').lower(); m = re.search(r'every (\d+) hours', c)
    return int(m.group(1)) if m else (24 if 'daily' in c else (1 if 'hour' in c else None))
rows = []
for s in ix['sources']:
    try: H = json.load(open(f"data/{s['id']}/health.json"))
    except Exception: H = None
    h = hrs(s['cadence']); ra = s.get('read_at')
    age = round((now - datetime.datetime.fromisoformat(ra.replace('Z', '+00:00'))).total_seconds() / 3600, 1) if ra else None
    exp = None if h is None else max(h, 12)
    state = 'archive (no schedule)' if exp is None else 'no read' if age is None else 'source problem' if H and H['problems'] else 'fresh' if age <= exp + 2 else 'late' if age <= 2 * exp + 2 else 'stale'
    blocked = None
    if H and H['problems']: blocked = '; '.join(f"{p['request']}: {','.join(map(str, p['status']))} {p['plain']} ({p['failed_in']})" for p in H['problems'][:6]) + (' ...' if len(H['problems']) > 6 else '')
    k = (H or {}).get('held') or {}
    rows.append({'id': s['id'], 'title': s['title'], 'source': s['publisher'], 'cadence_on_card': s['cadence'], 'collected': (H or {}).get('schedule', {}).get('really'), 'last_refresh_utc': ra, 'age_hours': age,
      'items_held': k.get('items'), 'items_noun': k.get('noun'), 'freshness': state, 'owner': 'cl-6.data@PrompTugal.dinis (collector); data owned by ' + s['publisher'], 'blocked_by': blocked,
      'cadence_advice': ((H or {}).get('cadence_advice') or {}).get('line'), 'health_url': f"https://data.promptugal.news/api/v1/{s['id']}/health.json", 'source_page': f"https://data.promptugal.news/sources/{s['id']}/"})
doc = {'about': 'Status of every dataset collected by cl-6.data for data.promptugal.news, from the live API and each source health file. A snapshot, regenerated at each wake by tools/status-summary.py.',
  'generated_utc': now.strftime('%Y-%m-%dT%H:%M:%SZ'), 'by': 'cl-6.data@PrompTugal.dinis', 'site': {'url': 'https://data.promptugal.news', 'version_url': 'https://data.promptugal.news/version.json', 'status_page': 'https://data.promptugal.news/status/'},
  'rule': 'fresh = last read no older than the expected gap plus 2 hours; expected gap = max(cadence, 12 hours) because collection runs twice a day (07:03 and 18:03 Lisbon)',
  'summary': {k: sum(1 for r in rows if r['freshness'] == k) for k in sorted({r['freshness'] for r in rows})},
  'known_blockers': [{'what': "vaults/*/latest/** regenerated by every collection but outside cl-6.data's write grant", 'state': 'interim ruling from cl-6.decisions: set aside, never commit; release data/ only', 'needs': 'Dinis to rule on a vaults/*/latest/** grant'},
    {'what': 'dev-gate release flow (work/cl-6.data) approved by cl-6.security but not applied', 'needs': 'P19 in force and IaC #34 and #35 merged'}], 'datasets': rows}
out = sys.argv[1] if len(sys.argv) > 1 else 'data-status.json'
json.dump(doc, open(out, 'w'), indent=1, ensure_ascii=False); open(out, 'a').write('\n')
print(doc['summary'], len(rows))
